import { BlockId, blockId } from '../world/blocks';
import { CHUNK_SIZE, Chunk, MIN_Y, blockIndex } from '../world/chunk';
import type { ChunkGenerator } from './generator';

/**
 * A deterministic stand-in for the future Rust/WASM `MapGen` (see MAP_WORLDS.md, phase A). It
 * proves the "map world" plumbing (generator kind in saves, workers and the server; spawn; the
 * edge of the map area) before mapcore exists.
 *
 * Everything is a pure function of world coordinates (the seed is ignored, like a real map):
 * - everywhere: bedrock, stone, dirt, and grass on top at `STUB_GROUND_Y`;
 * - inside `STUB_MAP_AREA` only: a crossroads of two road strips and a few box buildings, made of
 *   the phase B blocks (asphalt, road paint, paving, brick, plaster, concrete, roof tiles and
 *   slate), and the phase D shapes: raised paving-slab sidewalks, gabled stair roofs, glass-pane
 *   windows, a fenced garden, a stone wall and a railway with a curve. Outside the area the ground stays flat (as mapcore will do outside the bbox).
 */

/** y of the top ground block (grass / road surface). */
export const STUB_GROUND_Y = 64;

/** The fixed map area, in world block coordinates (inclusive). 8 x 8 chunks around the origin. */
export const STUB_MAP_AREA = { x0: -64, z0: -64, x1: 63, z1: 63 } as const;

/** Road strips (inclusive block ranges across the strip); they span the whole area. */
const ROAD_EW = { z0: 10, z1: 16 } as const; // runs along x
const ROAD_NS = { x0: 10, x1: 16 } as const; // runs along z

interface StubBuilding {
  x0: number;
  z0: number;
  x1: number;
  z1: number;
  /** Wall height in blocks above the ground; the roof is the top layer. */
  height: number;
  wall: number;
  roof: number;
  /** A gabled roof of these stairs (base block) and ridge slab, ridge along x; the flat roof stays as the ceiling. */
  gable?: { stairs: number; ridge: number };
}

/** Shaped blocks used by the stub (looked up by name: they have no `BlockId` constants). */
const S = {
  pavingSlab: blockId('paving_slab'),
  roofTilesStairs: blockId('roof_tiles_stairs'),
  roofTilesSlab: blockId('roof_tiles_slab'),
  roofSlateStairs: blockId('roof_slate_stairs'),
  roofSlateSlab: blockId('roof_slate_slab'),
  pane: blockId('glass_pane'),
  fence: blockId('wooden_fence'),
  wall: blockId('stone_wall'),
  rail: blockId('rail'),
  railEW: blockId('rail_ew'),
  /** Curve joining west and south (the curve texture turned three quarters). */
  railCurveWS: blockId('rail_curve_w'),
};

/** Railway: an east-west track along z = RAIL_Z, curving south at x = RAIL_X down to z = RAIL_END_Z. */
const RAIL_Z = -52;
const RAIL_X = 57;
const RAIL_START_X = -60;
const RAIL_END_Z = -12;

/** Rectangular rings (inclusive) of fence or wall around a building, with a gate gap at `gateX` on the south side. */
const ENCLOSURES: readonly { x0: number; z0: number; x1: number; z1: number; gateX: number; block: number }[] = [
  { x0: -38, z0: 22, x1: -18, z1: 42, gateX: -28, block: S.fence },
  { x0: -42, z0: -42, x1: -19, z1: -23, gateX: -31, block: S.wall },
];

/** Footprints are inclusive and never touch the roads or the open plaza around the spawn. */
export const STUB_BUILDINGS: readonly StubBuilding[] = [
  { x0: -40, z0: -40, x1: -21, z1: -25, height: 12, wall: BlockId.Brick, roof: BlockId.RoofSlate },
  { x0: -14, z0: -34, x1: -4, z1: -22, height: 6, wall: BlockId.Plaster, roof: BlockId.RoofTiles, gable: { stairs: S.roofTilesStairs, ridge: S.roofTilesSlab } },
  { x0: 22, z0: -40, x1: 44, z1: -22, height: 24, wall: BlockId.ConcreteBeige, roof: BlockId.ConcreteGray },
  { x0: -36, z0: 24, x1: -20, z1: 40, height: 8, wall: BlockId.ConcreteWhite, roof: BlockId.RoofSlate, gable: { stairs: S.roofSlateStairs, ridge: S.roofSlateSlab } },
  // Straddles the chunk border x = 32.
  { x0: 24, z0: 26, x1: 40, z1: 36, height: 16, wall: BlockId.ConcreteTeal, roof: BlockId.ConcreteLightGray },
  // A glass tower near the east edge of the area.
  { x0: 48, z0: -6, x1: 56, z1: 2, height: 40, wall: BlockId.Glass, roof: BlockId.ConcreteBlack },
];

/** Map worlds spawn on open ground at the centre (a paved plaza between the roads). */
export const STUB_SPAWN = { x: 0, y: STUB_GROUND_Y + 1, z: 0 } as const;

export function inStubMapArea(wx: number, wz: number): boolean {
  const a = STUB_MAP_AREA;
  return wx >= a.x0 && wx <= a.x1 && wz >= a.z0 && wz <= a.z1;
}

function isRoad(wx: number, wz: number): boolean {
  return inStubMapArea(wx, wz) && ((wz >= ROAD_EW.z0 && wz <= ROAD_EW.z1) || (wx >= ROAD_NS.x0 && wx <= ROAD_NS.x1));
}

/** Paved plaza around the spawn (inclusive half-size). */
const PLAZA = 3;

/**
 * Road surface block: asphalt with paving sidewalks on both edges, a dashed white centre line, and
 * a yellow stop line where each road meets the junction.
 */
function roadBlock(wx: number, wz: number): number {
  const inEW = wz >= ROAD_EW.z0 && wz <= ROAD_EW.z1;
  const inNS = wx >= ROAD_NS.x0 && wx <= ROAD_NS.x1;
  if (inEW && inNS) return BlockId.Asphalt; // the junction itself
  if (inEW) {
    if (wz === ROAD_EW.z0 || wz === ROAD_EW.z1) return BlockId.Paving;
    if (wx === ROAD_NS.x0 - 1 || wx === ROAD_NS.x1 + 1) return BlockId.RoadMarkingYellow;
    if (wz === (ROAD_EW.z0 + ROAD_EW.z1) >> 1 && (wx & 3) < 2) return BlockId.RoadMarking;
    return BlockId.Asphalt;
  }
  if (wx === ROAD_NS.x0 || wx === ROAD_NS.x1) return BlockId.Paving;
  if (wz === ROAD_EW.z0 - 1 || wz === ROAD_EW.z1 + 1) return BlockId.RoadMarkingYellow;
  if (wx === (ROAD_NS.x0 + ROAD_NS.x1) >> 1 && (wz & 3) < 2) return BlockId.RoadMarking;
  return BlockId.Asphalt;
}

/** Ground block of a non-road column inside the area: the plaza and a gravel-edged dirt path to the road. */
function groundBlock(wx: number, wz: number): number {
  if (Math.abs(wx) <= PLAZA && Math.abs(wz) <= PLAZA) return BlockId.Paving;
  // A path from the plaza east to the north-south road.
  if (wx > PLAZA && wx < ROAD_NS.x0 && wz >= -1 && wz <= 1) return wz === 0 ? BlockId.DirtPath : BlockId.Gravel;
  return BlockId.Grass;
}

/** Block of building `b` at world (wx, y, wz), which must lie inside its footprint. */
function buildingBlock(b: StubBuilding, wx: number, y: number, wz: number): number {
  const top = STUB_GROUND_Y + b.height;
  if (y === STUB_GROUND_Y) return BlockId.Planks; // floor
  if (y === top) return b.roof;
  const onX = wx === b.x0 || wx === b.x1;
  const onZ = wz === b.z0 || wz === b.z1;
  if (!onX && !onZ) return BlockId.Air; // hollow inside
  const level = y - STUB_GROUND_Y; // 1..height-1
  // Door: two blocks high in the middle of the south wall (z1).
  if (wz === b.z1 && !onX && wx === (b.x0 + b.x1) >> 1 && level <= 2) return BlockId.Air;
  // Windows: a glass band on every 4th level, not on corners, with mullions every 3 blocks.
  if (onX && onZ) return b.wall;
  const along = onZ ? wx : wz;
  if (b.wall !== BlockId.Glass && level % 4 === 2 && ((along % 3) + 3) % 3 !== 0) return S.pane;
  return b.wall;
}

/** Rows of a gabled roof above the flat roof (the ridge row included). */
function gableRows(b: StubBuilding): number {
  return b.gable === undefined ? 0 : ((b.z1 - b.z0) >> 1) + 1;
}

/**
 * Block of a gabled roof at world (wx, y, wz) above building `b`'s flat roof (y > top), inside its
 * footprint: stairs climbing from the north and south eaves to a slab ridge, and gable-end walls.
 */
function gableBlock(b: StubBuilding, wx: number, y: number, wz: number): number {
  const k = y - (STUB_GROUND_Y + b.height) - 1; // row, 0 = eaves
  const north = b.z0 + k;
  const south = b.z1 - k;
  if (north > south) return BlockId.Air;
  const { stairs, ridge } = b.gable!;
  // The north slope rises toward the south: its high side faces south (variant +2), and vice versa.
  if (north === south) return wz === north ? ridge : BlockId.Air;
  if (wz === north) return stairs + 2;
  if (wz === south) return stairs;
  if (wz > north && wz < south && (wx === b.x0 || wx === b.x1)) return b.wall;
  return BlockId.Air;
}

/** Fence / wall of an enclosure at column (wx, wz), if any. */
function enclosureAt(wx: number, wz: number): number | undefined {
  for (const e of ENCLOSURES) {
    const onX = (wx === e.x0 || wx === e.x1) && wz >= e.z0 && wz <= e.z1;
    const onZ = (wz === e.z0 || wz === e.z1) && wx >= e.x0 && wx <= e.x1;
    if (!onX && !onZ) continue;
    if (wz === e.z1 && Math.abs(wx - e.gateX) <= 1) return undefined; // gate
    return e.block;
  }
  return undefined;
}

/** Rail at column (wx, wz), if any. */
function railAt(wx: number, wz: number): number | undefined {
  if (wz === RAIL_Z && wx >= RAIL_START_X && wx < RAIL_X) return S.railEW;
  if (wz === RAIL_Z && wx === RAIL_X) return S.railCurveWS;
  if (wx === RAIL_X && wz > RAIL_Z && wz <= RAIL_END_Z) return S.rail;
  return undefined;
}

export class StubMapGenerator implements ChunkGenerator {
  readonly kind = 'map' as const;

  constructor(readonly seed = 0) {}

  /** Highest solid block of the column (roof or ground). */
  surfaceHeight(wx: number, wz: number): number {
    for (const b of STUB_BUILDINGS) {
      if (wx >= b.x0 && wx <= b.x1 && wz >= b.z0 && wz <= b.z1) {
        const top = STUB_GROUND_Y + b.height;
        for (let y = top + gableRows(b); y > top; y--) if (gableBlock(b, wx, y, wz) !== BlockId.Air) return y;
        return top;
      }
    }
    return STUB_GROUND_Y;
  }

  /** A label for the F3 overlay: inside or outside the map area. */
  biomeAt(wx: number, wz: number): string {
    const x = Math.floor(wx);
    const z = Math.floor(wz);
    if (!inStubMapArea(x, z)) return 'outside map';
    return isRoad(x, z) ? 'map: road' : 'map';
  }

  spawn(): { x: number; y: number; z: number } {
    return { ...STUB_SPAWN };
  }

  generateChunk(cx: number, cz: number): Chunk {
    const chunk = new Chunk(cx, cz);
    const blocks = chunk.blocks; // all air
    const x0 = cx * CHUNK_SIZE;
    const z0 = cz * CHUNK_SIZE;
    for (let lz = 0; lz < CHUNK_SIZE; lz++) {
      for (let lx = 0; lx < CHUNK_SIZE; lx++) {
        const wx = x0 + lx;
        const wz = z0 + lz;
        blocks[blockIndex(lx, MIN_Y, lz)] = BlockId.Bedrock;
        for (let y = MIN_Y + 1; y < STUB_GROUND_Y - 3; y++) blocks[blockIndex(lx, y, lz)] = BlockId.Stone;
        for (let y = STUB_GROUND_Y - 3; y < STUB_GROUND_Y; y++) blocks[blockIndex(lx, y, lz)] = BlockId.Dirt;
        const ground = isRoad(wx, wz) ? roadBlock(wx, wz) : inStubMapArea(wx, wz) ? groundBlock(wx, wz) : BlockId.Grass;
        blocks[blockIndex(lx, STUB_GROUND_Y, lz)] = ground;
        if (!inStubMapArea(wx, wz)) continue;
        const above = blockIndex(lx, STUB_GROUND_Y + 1, lz);
        // Sidewalks: a paving slab on the road's paved edges makes a half-block kerb.
        if (ground === BlockId.Paving && isRoad(wx, wz)) blocks[above] = S.pavingSlab;
        const fence = enclosureAt(wx, wz);
        if (fence !== undefined) blocks[above] = fence;
        const rail = railAt(wx, wz);
        if (rail !== undefined) {
          blocks[blockIndex(lx, STUB_GROUND_Y, lz)] = BlockId.Gravel; // ballast
          blocks[above] = rail;
        }
      }
    }
    // Buildings: intersect each footprint with this chunk.
    for (const b of STUB_BUILDINGS) {
      const bx0 = Math.max(b.x0, x0);
      const bx1 = Math.min(b.x1, x0 + CHUNK_SIZE - 1);
      const bz0 = Math.max(b.z0, z0);
      const bz1 = Math.min(b.z1, z0 + CHUNK_SIZE - 1);
      if (bx0 > bx1 || bz0 > bz1) continue;
      for (let y = STUB_GROUND_Y; y <= STUB_GROUND_Y + b.height; y++) {
        for (let wz = bz0; wz <= bz1; wz++) {
          for (let wx = bx0; wx <= bx1; wx++) blocks[blockIndex(wx - x0, y, wz - z0)] = buildingBlock(b, wx, y, wz);
        }
      }
      const top = STUB_GROUND_Y + b.height;
      for (let y = top + 1; y <= top + gableRows(b); y++) {
        for (let wz = bz0; wz <= bz1; wz++) {
          for (let wx = bx0; wx <= bx1; wx++) {
            const id = gableBlock(b, wx, y, wz);
            if (id !== BlockId.Air) blocks[blockIndex(wx - x0, y, wz - z0)] = id;
          }
        }
      }
    }
    // A lumen block lamp on each corner of the junction, so roads are visible at night.
    for (const [lx, lz] of [
      [ROAD_NS.x0 - 1, ROAD_EW.z0 - 1],
      [ROAD_NS.x1 + 1, ROAD_EW.z0 - 1],
      [ROAD_NS.x0 - 1, ROAD_EW.z1 + 1],
      [ROAD_NS.x1 + 1, ROAD_EW.z1 + 1],
    ] as const) {
      const x = lx - x0;
      const z = lz - z0;
      if (x < 0 || x >= CHUNK_SIZE || z < 0 || z >= CHUNK_SIZE) continue;
      for (let y = STUB_GROUND_Y + 1; y <= STUB_GROUND_Y + 3; y++) blocks[blockIndex(x, y, z)] = BlockId.Log;
      blocks[blockIndex(x, STUB_GROUND_Y + 4, z)] = BlockId.LumenBlock;
    }
    chunk.recount();
    return chunk;
  }
}
