/**
 * Crafting (Milestone 7). Recipes are plain data; `matchRecipe` checks a square grid (2x2 in the
 * inventory, 3x3 at a workbench) and is pure.
 *
 * - Shaped recipes match wherever the pattern sits in the grid, and also mirrored left-right.
 * - Shapeless recipes match any arrangement of exactly their ingredients.
 *
 * There is no furnace: "smelting" is done by crafting with coal as fuel (documented choice):
 *   iron ore + coal -> iron ingot, 4 sand + coal -> 4 glass, 4 rubble + coal -> 4 stone,
 *   raw meat + coal -> cooked meat (Milestone 8; 3 raw meat + coal -> 3 cooked meat too).
 *
 * Map-world blocks (phase B) are craftable from what survival already has; asphalt and brick are
 * "fired" with coal the same way. Only gray and white concrete are craftable (there are no dyes);
 * the other colours are creative-palette only.
 */
import { itemId, type ItemStack, type Slot } from './items';

export interface RecipeResult {
  item: string;
  count: number;
}

export interface ShapedRecipeDef {
  id: string;
  type: 'shaped';
  /** Rows of single-character keys; ' ' is an empty cell. */
  pattern: string[];
  key: Record<string, string>;
  result: RecipeResult;
}

export interface ShapelessRecipeDef {
  id: string;
  type: 'shapeless';
  ingredients: string[];
  result: RecipeResult;
}

export type RecipeDef = ShapedRecipeDef | ShapelessRecipeDef;

const TOOL_MATERIALS: readonly [string, string][] = [
  ['wooden', 'planks'],
  ['stone', 'rubble'],
  ['iron', 'iron_ingot'],
];

function toolRecipes(): RecipeDef[] {
  const out: RecipeDef[] = [];
  for (const [mat, material] of TOOL_MATERIALS) {
    const key = { M: material, S: 'stick' };
    out.push(
      { id: `${mat}_pickaxe`, type: 'shaped', pattern: ['MMM', ' S ', ' S '], key, result: { item: `${mat}_pickaxe`, count: 1 } },
      { id: `${mat}_axe`, type: 'shaped', pattern: ['MM', 'MS', ' S'], key, result: { item: `${mat}_axe`, count: 1 } },
      { id: `${mat}_shovel`, type: 'shaped', pattern: ['M', 'S', 'S'], key, result: { item: `${mat}_shovel`, count: 1 } },
      { id: `${mat}_sword`, type: 'shaped', pattern: ['M', 'M', 'S'], key, result: { item: `${mat}_sword`, count: 1 } },
    );
  }
  return out;
}

