/** A recipe with names resolved to item IDs. */
export interface Recipe {
  id: string;
  type: 'shaped' | 'shapeless';
  /** Shaped: trimmed pattern size and cells (item ID, -1 = empty), row-major. */
  width: number;
  height: number;
  cells: number[];
  /** Shapeless: sorted ingredient IDs. */
  ingredients: number[];
  result: { item: number; count: number };
}

/** Resolves names and trims empty border rows/columns of shaped patterns. Throws on bad data. */
export function compileRecipe(def: RecipeDef): Recipe {
  const result = { item: itemId(def.result.item), count: def.result.count };
  if (def.type === 'shapeless') {
    return { id: def.id, type: 'shapeless', width: 0, height: 0, cells: [], ingredients: def.ingredients.map(itemId).sort((a, b) => a - b), result };
  }
  const rows = def.pattern;
  const w0 = Math.max(...rows.map((r) => r.length));
  const cellAt = (x: number, y: number): number => {
    const ch = rows[y]?.[x] ?? ' ';
    if (ch === ' ') return -1;
    const name = def.key[ch];
    if (!name) throw new Error(`Recipe ${def.id}: key '${ch}' is not defined`);
    return itemId(name);
  };
  let minX = Infinity, minY = Infinity, maxX = -1, maxY = -1;
  for (let y = 0; y < rows.length; y++) {
    for (let x = 0; x < w0; x++) {
      if (cellAt(x, y) < 0) continue;
      minX = Math.min(minX, x); maxX = Math.max(maxX, x);
      minY = Math.min(minY, y); maxY = Math.max(maxY, y);
    }
  }
  if (maxX < 0) throw new Error(`Recipe ${def.id}: empty pattern`);
  const width = maxX - minX + 1;
  const height = maxY - minY + 1;
  const cells: number[] = [];
  for (let y = minY; y <= maxY; y++) for (let x = minX; x <= maxX; x++) cells.push(cellAt(x, y));
  return { id: def.id, type: 'shaped', width, height, cells, ingredients: [], result };
}

export const RECIPES: readonly Recipe[] = RECIPE_DEFS.map(compileRecipe);

export interface CraftMatch {
  recipe: Recipe;
  result: ItemStack;
}

/**
 * Finds the recipe matching a `size` x `size` grid (row-major), or null. Recipes larger than the
 * grid can never match, so 3x3 recipes need a workbench.
 */
export function matchRecipe(grid: readonly Slot[], size: number, recipes: readonly Recipe[] = RECIPES): CraftMatch | null {
  // Bounding box of the filled cells.
  let minX = Infinity, minY = Infinity, maxX = -1, maxY = -1;
  const filled: number[] = [];
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const s = grid[y * size + x];
      if (!s) continue;
      filled.push(s.item);
      minX = Math.min(minX, x); maxX = Math.max(maxX, x);
      minY = Math.min(minY, y); maxY = Math.max(maxY, y);
    }
  }
  if (filled.length === 0) return null;
  const w = maxX - minX + 1;
  const h = maxY - minY + 1;
  const at = (x: number, y: number): number => grid[(minY + y) * size + minX + x]?.item ?? -1;
  filled.sort((a, b) => a - b);

  for (const r of recipes) {
    if (r.type === 'shapeless') {
      if (r.ingredients.length !== filled.length) continue;
      if (r.ingredients.every((id, i) => id === filled[i])) return { recipe: r, result: { item: r.result.item, count: r.result.count, damage: 0 } };
      continue;
    }
    if (r.width !== w || r.height !== h) continue;
    let direct = true;
    let mirrored = true;
    for (let y = 0; y < h && (direct || mirrored); y++) {
      for (let x = 0; x < w; x++) {
        const g = at(x, y);
        if (r.cells[y * w + x] !== g) direct = false;
        if (r.cells[y * w + (w - 1 - x)] !== g) mirrored = false;
      }
    }
    if (direct || mirrored) return { recipe: r, result: { item: r.result.item, count: r.result.count, damage: 0 } };
  }
  return null;
}

/** Uses up one crafting's worth of ingredients: one item from every filled cell. */
export function consumeIngredients(grid: Slot[]): void {
  for (let i = 0; i < grid.length; i++) {
    const s = grid[i];
    if (!s) continue;
    s.count--;
    if (s.count <= 0) grid[i] = null;
  }
}

/** Matches, consumes and returns the result, or null when nothing matches. */
export function craftOnce(grid: Slot[], size: number): ItemStack | null {
  const m = matchRecipe(grid, size);
  if (!m) return null;
  consumeIngredients(grid);
  return m.result;
}
