/**
 * Mob type definitions (Milestone 8). Everything about a kind of mob is data here: body size,
 * speed, health, drops, the box model, spawn rules and behaviour. Saves refer to mobs by `name`.
 *
 * All names are original: the passive mobs are real-world animals, the hostile ones are invented
 * (the Gloomwalker, a shambling melee night-walker, and the Bilespitter, a squat ranged spitter).
 */

/** Texture layer names for a box: per face. Missing faces fall back to `side`. */
export interface PartFaces {
  side: string;
  top?: string;
  bottom?: string;
  /** Model-forward face (local -Z). */
  front?: string;
  back?: string;
}

export type PartRole = 'body' | 'head' | 'leg';

/**
 * One box of a mob model, in model space: blocks, origin at the feet centre, the mob facing -Z.
 * The box is `size` large and placed with its pivot at `pivot`; `offset` is the box's min corner
 * relative to the pivot. Heads turn around their pivot (yaw/pitch); legs swing around theirs.
 */
export interface ModelPart {
  role: PartRole;
  pivot: readonly [number, number, number];
  offset: readonly [number, number, number];
  size: readonly [number, number, number];
  faces: PartFaces;
  /** Legs: +1 or -1, which half of the walk cycle this leg swings in. */
  phase?: number;
}

export interface DropEntry {
  /** Item name. */
  item: string;
  min: number;
  max: number;
  /** Probability that this entry drops at all (default 1). */
  chance?: number;
}

export interface SpawnRule {
  /** Passive mobs spawn on grass in daylight-lit areas; hostile ones in the dark (see spawnRules.ts). */
  category: 'passive' | 'hostile';
  /** Relative weight when choosing which mob of the category spawns. */
  weight: number;
  /** Mobs per spawned group (inclusive). */
  groupMin: number;
  groupMax: number;
}

export interface MeleeAttack {
  kind: 'melee';
  damage: number;
  /** Reach beyond touching (between body edges), blocks. */
  reach: number;
  cooldown: number;
  /** Horizontal knockback speed given to the player, blocks/s. */
  knockback: number;
}

export interface RangedAttack {
  kind: 'ranged';
  damage: number;
  /** Fires when the target is within this distance and in sight. */
  range: number;
  /** Tries to keep at least this distance (stops approaching). */
  preferredDistance: number;
  cooldown: number;
  projectileSpeed: number;
  knockback: number;
}

export interface Behaviour {
  /** Seconds a passive mob runs from what hit it. */
  fleeSeconds: number;
  /** Speed multiplier while fleeing / chasing. */
  fleeSpeedFactor: number;
  chaseSpeedFactor: number;
  /** Hostiles notice the player within this distance (with line of sight). */
  sightRange: number;
  attack?: MeleeAttack | RangedAttack;
  /** Takes damage in direct daylight (sky exposed, day). */
  burnsInDaylight: boolean;
}

export interface MobTypeDef {
  /** Stable save name. */
  name: string;
  label: string;
  hostile: boolean;
  halfWidth: number;
  height: number;
  /** Eye height above the feet (head look target / line-of-sight origin). */
  eyeHeight: number;
  /** Walk speed, blocks/s. */
  speed: number;
  maxHealth: number;
  drops: readonly DropEntry[];
  model: readonly ModelPart[];
  spawn: SpawnRule;
  behaviour: Behaviour;
  /** Text after "You were ..." on the death screen. */
  killVerb: string;
}

const leg = (x: number, z: number, h: number, w: number, faces: PartFaces, phase: number): ModelPart => ({
  role: 'leg',
  pivot: [x, h, z],
  offset: [-w / 2, -h, -w / 2],
  size: [w, h, w],
  faces,
  phase,
});

/** Four legs at the corners of a body footprint. */
function fourLegs(dx: number, dz: number, h: number, w: number, faces: PartFaces): ModelPart[] {
  return [leg(-dx, -dz, h, w, faces, 1), leg(dx, -dz, h, w, faces, -1), leg(-dx, dz, h, w, faces, -1), leg(dx, dz, h, w, faces, 1)];
}

