const BY_NAME = new Map(MOB_TYPES.map((t) => [t.name, t]));

export function mobTypeByName(name: string): MobTypeDef | undefined {
  return BY_NAME.get(name);
}

/** Every texture layer name used by mob models (the client generates one image per name). */
export function mobTextureNames(): string[] {
  const names = new Set<string>(['projectile']);
  for (const t of [...MOB_TYPES, PLAYER_AVATAR]) {
    for (const p of t.model) for (const n of [p.faces.side, p.faces.top, p.faces.bottom, p.faces.front, p.faces.back]) if (n) names.add(n);
  }
  return [...names];
}
