// Mesh worker: turns padded 18^3 block + light copies into packed section meshes.
// Typed against the DOM lib (the client tsconfig); `postMessage(msg, { transfer })` has the same
// shape on Window and DedicatedWorkerGlobalScope.
import { meshSection } from '@voxel/shared';
import type { MeshRequest, MeshResponse } from './meshProtocol';

self.onmessage = (e: MessageEvent<MeshRequest>) => {
  const { job, key, version, padded, light } = e.data;
  const t0 = performance.now();
  const mesh = meshSection(padded, light);
  const res: MeshResponse = { job, key, version, mesh, padded, light, ms: performance.now() - t0 };
  self.postMessage(res, {
    transfer: [
      mesh.opaque.vertices.buffer,
      mesh.opaque.indices.buffer,
      mesh.transparent.vertices.buffer,
      mesh.transparent.indices.buffer,
      padded.buffer,
      light.buffer,
    ],
  });
};
