import { BLOCKS, BlockId } from '../world/blocks';
import { CHUNK_VOLUME, LEGACY_CHUNK_VOLUME, MAX_Y, MIN_Y } from '../world/chunk';

/**
 * Chunk block serialization for saves (pure, no DOM / streams).
 *
 * A saved chunk is `{ palette, rle }`:
 * - `palette`: the block *names* used in this chunk, in local-index order. Names (not IDs) are
 *   stored so block IDs can be renumbered in later versions; `decodeChunkBlocks` maps each name to
 *   the current ID (unknown names become air).
 * - `rle`: run-length encoded local palette indices over `Chunk.blocks` in its y-major order, as
 *   unsigned LEB128 varint pairs `(paletteIndex, runLength)`. Runs sum to exactly CHUNK_VOLUME.
 *
 * Format 2 (phase C) is 384 blocks tall (y -64..319). Format 1 chunks (y 0..255, runs summing to
 * LEGACY_CHUNK_VOLUME) are still read: `decodeChunkBlocks` pads them with stone below y 0 (bedrock
 * at the new floor) and air above y 255. The length tells them apart, so the server's files and
 * network data need no separate version.
 *
 * Light is never stored: it is derived from blocks and recomputed on load. The client may further
 * compress `rle` with CompressionStream (see packages/client/src/storage/compression.ts).
 */

/** Bump when the encoded layout changes; decoders must accept every older version. */
export const CHUNK_FORMAT_VERSION = 2;

export interface EncodedChunkBlocks {
  /** Block names used in this chunk; RLE values index into this list. */
  palette: string[];
  /** Varint (index, run) pairs. */
  rle: Uint8Array;
}

export interface DecodedChunkBlocks {
  blocks: Uint16Array;
  /** True when the data was a format-1 (y 0..255) chunk and was padded to the current height. */
  upgraded?: boolean;
  /** Saved names that are not registered blocks any more (decoded as air). */
  unknown: string[];
}

/** Current block names in ID order (the global palette a world records in its meta). */
export function currentBlockPalette(): string[] {
  return BLOCKS.map((b) => b.name);
}

const DEFAULT_NAMES: readonly string[] = currentBlockPalette();
const DEFAULT_LOOKUP = new Map(DEFAULT_NAMES.map((n, i) => [n, i]));

/** Name -> current ID. Returns undefined for names that are not registered. */
export type BlockNameResolver = (name: string) => number | undefined;

export const resolveCurrentBlockName: BlockNameResolver = (name) => DEFAULT_LOOKUP.get(name);

/** Growable byte buffer for varints. */
class ByteWriter {
  private buf = new Uint8Array(4096);
  length = 0;

  varint(v: number): void {
    if (this.length + 5 > this.buf.length) {
      const next = new Uint8Array(this.buf.length * 2);
      next.set(this.buf);
      this.buf = next;
    }
    while (v >= 0x80) {
      this.buf[this.length++] = (v & 0x7f) | 0x80;
      v >>>= 7;
    }
    this.buf[this.length++] = v;
  }

  finish(): Uint8Array {
    return this.buf.slice(0, this.length);
  }
}

/** Run-length encodes a block array (any length) as varint pairs of raw values. */
export function rleEncode(values: Uint16Array): Uint8Array {
  const w = new ByteWriter();
  const n = values.length;
  let i = 0;
  while (i < n) {
    const v = values[i]!;
    let j = i + 1;
    while (j < n && values[j] === v) j++;
    w.varint(v);
    w.varint(j - i);
    i = j;
  }
  return w.finish();
}

/** Number of values encoded in RLE data (sum of the runs); throws if malformed. */
export function rleCount(data: Uint8Array): number {
  let p = 0;
  let count = 0;
  const readVarint = (): number => {
    let result = 0;
    let shift = 0;
    for (;;) {
      if (p >= data.length) throw new Error('rleCount: truncated varint');
      const b = data[p++]!;
      result += (b & 0x7f) * 2 ** shift;
      if (b < 0x80) return result;
      shift += 7;
      if (shift > 35) throw new Error('rleCount: varint too long');
    }
  };
  while (p < data.length) {
    readVarint();
    count += readVarint();
  }
  return count;
}

/**
 * Widens a format-1 chunk (y 0..255) to the current height: bedrock at MIN_Y, stone up to y -1,
 * the old blocks from y 0, air above y 255.
 */
export function padLegacyChunk(legacy: Uint16Array): Uint16Array {
  if (legacy.length !== LEGACY_CHUNK_VOLUME) throw new Error(`padLegacyChunk: expected ${LEGACY_CHUNK_VOLUME} blocks`);
  return padFromY0(legacy);
}

/**
 * Places blocks laid out from world y 0 upward (any whole number of layers up to MAX_Y) into a
 * full-height chunk over the deep layer: bedrock at MIN_Y, stone up to y -1, air above the input.
 */
export function padFromY0(fromY0: Uint16Array): Uint16Array {
  const below = -MIN_Y * 256; // layers under y 0
  if (fromY0.length % 256 !== 0 || below + fromY0.length > CHUNK_VOLUME) throw new Error(`padFromY0: ${fromY0.length} blocks is not whole layers from y 0 to at most ${MAX_Y}`);
  const out = new Uint16Array(CHUNK_VOLUME);
  out.fill(BlockId.Bedrock, 0, 256);
  out.fill(BlockId.Stone, 256, below);
  out.set(fromY0, below);
  return out;
}

/** Inverse of `rleEncode`. Throws if the data is malformed or does not fill exactly `length` values. */
export function rleDecode(data: Uint8Array, length: number, out: Uint16Array = new Uint16Array(length)): Uint16Array {
  if (out.length !== length) throw new Error(`rleDecode: output must have ${length} entries`);
  let p = 0;
  const readVarint = (): number => {
    let result = 0;
    let shift = 0;
    for (;;) {
      if (p >= data.length) throw new Error('rleDecode: truncated varint');
      const b = data[p++]!;
      result += (b & 0x7f) * 2 ** shift;
      if (b < 0x80) return result;
      shift += 7;
      if (shift > 35) throw new Error('rleDecode: varint too long');
    }
  };
  let o = 0;
  while (p < data.length) {
    const v = readVarint();
    const run = readVarint();
    if (run <= 0 || o + run > length) throw new Error('rleDecode: run overflows the output');
    if (v > 0xffff) throw new Error('rleDecode: value out of range');
    out.fill(v, o, o + run);
    o += run;
  }
  if (o !== length) throw new Error(`rleDecode: decoded ${o} values, expected ${length}`);
  return out;
}

/**
 * Encodes chunk blocks with a chunk-local palette of block names.
 * @param idToName Name for each block ID (defaults to the current registry).
 */
export function encodeChunkBlocks(blocks: Uint16Array, idToName: readonly string[] = DEFAULT_NAMES): EncodedChunkBlocks {
  if (blocks.length !== CHUNK_VOLUME) throw new Error(`encodeChunkBlocks: expected ${CHUNK_VOLUME} blocks`);
  const localOf = new Int32Array(65536).fill(-1);
  const palette: string[] = [];
  const local = new Uint16Array(CHUNK_VOLUME);
  for (let i = 0; i < CHUNK_VOLUME; i++) {
    const id = blocks[i]!;
    let li = localOf[id]!;
    if (li < 0) {
      const name = idToName[id];
      if (name === undefined) throw new Error(`encodeChunkBlocks: block id ${id} has no name`);
      li = localOf[id] = palette.length;
      palette.push(name);
    }
    local[i] = li;
  }
  return { palette, rle: rleEncode(local) };
}

/**
 * Decodes `encodeChunkBlocks` output, remapping palette names to current IDs. Names the resolver
 * does not know decode as air and are reported in `unknown`.
 */
export function decodeChunkBlocks(
  encoded: EncodedChunkBlocks,
  resolve: BlockNameResolver = resolveCurrentBlockName,
): DecodedChunkBlocks {
  const unknown: string[] = [];
  const remap = new Uint16Array(encoded.palette.length);
  encoded.palette.forEach((name, i) => {
    const id = resolve(name);
    if (id === undefined) {
      unknown.push(name);
      remap[i] = BlockId.Air;
    } else {
      remap[i] = id;
    }
  });
  const legacy = rleCount(encoded.rle) === LEGACY_CHUNK_VOLUME;
  const length = legacy ? LEGACY_CHUNK_VOLUME : CHUNK_VOLUME;
  const blocks = rleDecode(encoded.rle, length);
  for (let i = 0; i < length; i++) {
    const li = blocks[i]!;
    if (li >= remap.length) throw new Error(`decodeChunkBlocks: palette index ${li} out of range`);
    blocks[i] = remap[li]!;
  }
  return legacy ? { blocks: padLegacyChunk(blocks), unknown, upgraded: true } : { blocks, unknown };
}

/**
 * Builds an old-ID -> current-ID table from a saved global palette (names in old ID order). Unknown
 * names map to air and are listed in `unknown`.
 */
export function buildPaletteRemap(
  savedPalette: readonly string[],
  resolve: BlockNameResolver = resolveCurrentBlockName,
): { remap: Uint16Array; unknown: string[] } {
  const remap = new Uint16Array(savedPalette.length);
  const unknown: string[] = [];
  savedPalette.forEach((name, i) => {
    const id = resolve(name);
    if (id === undefined) unknown.push(name);
    remap[i] = id ?? BlockId.Air;
  });
  return { remap, unknown };
}
